function ConversationPreviewIcon({ type }) {
	const normalizedType = String(type || '').toLowerCase();
	const props = { size: 15, strokeWidth: 2, className: 'shrink-0 text-[#667781]' };
	if (['image', 'photo'].includes(normalizedType)) {
		return <CameraPreviewIcon className={props.className} />;
	}
	if (['audio', 'ptt', 'voice'].includes(normalizedType)) {
		return (
			<svg
				xmlns="http://www.w3.org/2000/svg"
				width="15"
				height="15"
				viewBox="0 0 24 24"
				fill="none"
				stroke="currentColor"
				strokeWidth="2"
				strokeLinecap="round"
				strokeLinejoin="round"
				className={props.className}
				aria-hidden="true"
			>
				<path d="M12 19v3" />
				<path d="M19 10v2a7 7 0 0 1-14 0v-2" />
				<rect x="9" y="2" width="6" height="13" rx="3" fill="currentColor" />
			</svg>
		);
	}
	if (['location', 'live_location'].includes(normalizedType)) return <MapPin {...props} />;
	if (normalizedType === 'video') return <Video {...props} />;
	if (normalizedType === 'document') {
		return (
			<img
				src={whatsappFileIconSrc('file')}
				alt=""
				aria-hidden="true"
				className={`h-4 w-4 shrink-0 object-contain ${props.className || ''}`}
			/>
		);
	}
	if (normalizedType === 'sticker') {
		return (
			<img
				src="/sticker.svg"
				alt=""
				aria-hidden="true"
				className="h-4 w-4 shrink-0 object-contain"
			/>
		);
	}
	return null;
}

function WhatsAppFormattedText({
	text,
	mentionDirectory = null,
	mentionLabels = null,
	forceMarkdown = false,
}) {
	if (forceMarkdown || looksLikeMarkdown(text)) {
		return <MarkdownMessage content={text} className="wa-chat-md" />;
	}
	return parseWhatsAppBold(text).flatMap((part, partIndex) =>
		messageTextSegments(part.text).map((segment, segmentIndex) => {
			const key = `${partIndex}:${segmentIndex}`;
			const content =
				segment.type === 'link' ? (
					<a
						key={key}
						href={segment.href}
						target="_blank"
						rel="noreferrer"
						className="wa-message-link font-medium text-[#027EB5] underline decoration-[#027EB5]/50 underline-offset-2 hover:decoration-current dark:text-[#53BDEB]"
						onClick={event => event.stopPropagation()}
					>
						{segment.text}
					</a>
				) : segment.type === 'mention' ? (
					<span key={key} className="wa-message-mention">
						{resolveWhatsAppMentionLabel(
							segment.text,
							mentionDirectory,
							mentionLabels,
						).replace(/ /g, '\u00A0')}
					</span>
				) : segment.type === 'emoji' ? (
					<span key={key} className="wa-message-emoji">
						{segment.text}
					</span>
				) : (
					segment.text
				);
			let node =
				typeof content === 'string' ? (
					<span key={key} className="wa-message-run">
						{content}
					</span>
				) : (
					content
				);
			if (part.code) {
				node = (
					<code key={key} className="rounded bg-black/10 px-1 py-0.5 font-mono text-[0.92em] dark:bg-white/10">
						{content}
					</code>
				);
			}
			if (part.bold) {
				node = (
					<strong key={`${key}-b`} className="font-bold">
						{node}
					</strong>
				);
			}
			if (part.italic) {
				node = (
					<em key={`${key}-i`} className="italic">
						{node}
					</em>
				);
			}
			if (part.strike) {
				node = (
					<span key={`${key}-s`} className="line-through">
						{node}
					</span>
				);
			}
			return node;
		}),
	);
}

/**
 * The video pulled from a social link, shown under the link preview it belongs to.
 *
 * Renders nothing until a download is actually requested, so an ordinary shared link
 * keeps looking exactly as it does today.
 */
function SocialVideoDownload({
	state,
	locale,
	onRetry,
	labels,
	conversationId,
	conversations,
	onAddToStory,
}) {
	if (!state) return null;
	const ar = locale === 'ar';

	if (state.status === 'pending') {
		return (
			<div className="mb-1 flex items-center gap-2.5 rounded-xl border border-black/5 bg-black/[0.045] px-3 py-2.5 dark:border-white/10 dark:bg-white/[0.07]">
				<Loader2 size={16} className="shrink-0 animate-spin text-[#027EB5] dark:text-[#53BDEB]" />
				<span className="min-w-0 flex-1 truncate text-[12px] opacity-75">
					{ar ? 'جارٍ تحميل الفيديو…' : 'Downloading video…'}
				</span>
			</div>
		);
	}

	if (state.status === 'failed') {
		return (
			<div className="mb-1 rounded-xl border border-red-500/25 bg-red-500/8 px-3 py-2.5">
				<div className="flex items-start gap-2.5">
					<AlertCircle size={16} className="mt-0.5 shrink-0 text-red-600 dark:text-red-400" />
					<span className="min-w-0 flex-1 text-[12px] leading-snug text-red-700 dark:text-red-300">
						{state.errorMessage || (ar ? 'فشل تحميل الفيديو' : 'Could not download this video')}
					</span>
				</div>
				<button
					type="button"
					onPointerDown={event => event.stopPropagation()}
					onClick={event => {
						event.preventDefault();
						event.stopPropagation();
						onRetry();
					}}
					className="mt-2 inline-flex items-center gap-1.5 rounded-full bg-red-600/10 px-2.5 py-1 text-[11px] font-semibold text-red-700 transition-colors hover:bg-red-600/20 dark:text-red-300"
				>
					<RefreshCw size={12} strokeWidth={2.4} />
					{ar ? 'إعادة المحاولة' : 'Retry'}
				</button>
			</div>
		);
	}

	if (state.status !== 'ready' || !state.url) return null;
	return (
		<div className="mb-1">
			<div className="overflow-hidden rounded-xl">
				<ChatVideoPlayer
					url={absoluteApiUrl(state.url)}
					cacheKey={state.id}
					durationHint={state.durationSeconds || 0}
					playLabel={labels.playVideo || labels.play || 'Play'}
					pauseLabel={labels.pauseVideo || 'Pause'}
					muteLabel={labels.muteVideo || 'Mute'}
					unmuteLabel={labels.unmuteVideo || 'Unmute'}
					expandLabel={labels.expandVideo || 'Expand video'}
					collapseLabel={labels.exitVideoFullscreen || 'Exit fullscreen'}
					closeLabel={labels.close || 'Close'}
					speedLabel={labels.playbackSpeed || 'Playback speed'}
					moreLabel={labels.moreActions || 'More'}
				/>
			</div>
			<SocialVideoActions
				downloadId={state.id}
				locale={locale}
				conversationId={conversationId}
				conversations={conversations}
				onAddToStory={onAddToStory}
			/>
		</div>
	);
}

function MessageLinkPreview({ text, labels }) {
	const link = firstMessageLink(text);
	if (!link) return null;
	const copyLink = async event => {
		event.preventDefault();
		event.stopPropagation();
		try {
			await navigator.clipboard.writeText(link.href);
			toast.success(labels.linkCopied || 'Link copied');
		} catch {
			toast.error(labels.copyLinkFailed || 'Could not copy link');
		}
	};
	return (
		<div className="mb-1 flex min-w-0 items-center gap-2 rounded-xl border border-black/5 bg-black/[0.045] p-2.5 dark:border-white/10 dark:bg-white/[0.07]">
			<a
				href={link.href}
				target="_blank"
				rel="noreferrer"
				onClick={event => event.stopPropagation()}
				className="flex min-w-0 flex-1 items-center gap-3 no-underline transition-colors"
			>
				<span className="grid h-10 w-10 shrink-0 place-items-center rounded-xl bg-white text-[#027EB5] shadow-sm dark:bg-slate-700 dark:text-[#53BDEB]">
					<Globe2 size={20} />
				</span>
				<span className="min-w-0 flex-1">
					<span className="block truncate text-sm font-bold">{link.hostname}</span>
					<span dir="ltr" className="block truncate text-[11px] opacity-60">
						{link.displayUrl}
					</span>
				</span>
			</a>
			<div className="flex shrink-0 items-center gap-0.5">
				<button
					type="button"
					onPointerDown={event => event.stopPropagation()}
					onClick={copyLink}
					title={labels.copyLink}
					aria-label={labels.copyLink}
					className="grid h-8 w-8 place-items-center rounded-full text-[#027EB5] transition-colors hover:bg-black/8 dark:text-[#53BDEB]"
				>
					<Copy size={15} strokeWidth={2.2} />
				</button>
				<a
					href={link.href}
					target="_blank"
					rel="noreferrer"
					onClick={event => event.stopPropagation()}
					title={labels.openLink}
					aria-label={labels.openLink}
					className="grid h-8 w-8 place-items-center rounded-full text-[#027EB5] no-underline transition-colors hover:bg-black/8 dark:text-[#53BDEB]"
				>
					<ExternalLink size={16} />
				</a>
			</div>
		</div>
	);
}

const waAvatarRefreshInFlight = new Set();

function requestWhatsAppAvatarRefresh(conversationId, onFreshUrl) {
	const id = String(conversationId || '').trim();
	if (!id || waAvatarRefreshInFlight.has(id)) return;
	waAvatarRefreshInFlight.add(id);
	api
		.post(`/whatsapp/conversations/${id}/avatar/refresh`)
		.then(({ data }) => {
			const next = String(data?.avatarUrl || '').trim();
			if (next) onFreshUrl?.(next);
		})
		.catch(() => undefined)
		.finally(() => {
			setTimeout(() => waAvatarRefreshInFlight.delete(id), 12_000);
		});
}

